 'snapshot_fingerprint',c->>'body_sha256','receipt_id','00000000-0000-4000-8000-000000000042','destination_organization_id',p->>'destination_organization_id','shadow_only',true);
 begin perform public.finish_operations_catering_finance_delivery_v1((p->>'operations_organization_id')::uuid,delivery,'fixture-owner-001',(c->>'lease_token')::uuid,'delivered',receipt||'{"outcome":null}',null);
 raise exception 'null receipt outcome accepted';exception when invalid_parameter_value then null;end;
 begin perform public.finish_operations_catering_finance_delivery_v1((p->>'operations_organization_id')::uuid,delivery,'fixture-owner-001',(c->>'lease_token')::uuid,'delivered',receipt||jsonb_build_object('snapshot_fingerprint',repeat('0',64)),null);
 raise exception 'unbound receipt acknowledged';exception when invalid_parameter_value then null;end;
 begin perform public.finish_operations_catering_finance_delivery_v1((p->>'operations_organization_id')::uuid,delivery,'fixture-owner-002',(c->>'lease_token')::uuid,'delivered',receipt,null);
 raise exception 'foreign lease finished';exception when insufficient_privilege then null;end;
 r:=public.finish_operations_catering_finance_delivery_v1((p->>'operations_organization_id')::uuid,delivery,'fixture-owner-001',(c->>'lease_token')::uuid,'delivered',receipt,null);
 if r->>'status'<>'delivered' or r->>'source_outbox_status'<>'parked' then raise exception 'delivery altered original parked outbox';end if;
 if exists(select 1 from public.operations_catering_cost_outbox where status<>'parked') then raise exception 'legacy parked outbox activated';end if;
 -- The normalized capture-mismatch enum can finish a lease as blocked, not leave it stranded.
