 perform public.publish_operations_catering_cost_v1(p->'snapshot',p->>'raw_entry',null,(p->>'source_mapping_id')::uuid,p->>'source_request_hash',1,'isolated-native-finance-correction');
 select id into oid from public.operations_catering_cost_outbox where source_revision=2;
 update operations_catering_private.finance_delivery_maps set enabled=false;
