 r:=public.finish_operations_catering_finance_delivery_v1((p->>'operations_organization_id')::uuid,delivery,'fixture-owner-003',(c->>'lease_token')::uuid,'blocked',null,'catering_finance_capture_or_configuration_invalid');
 if r->>'status'<>'blocked' then raise exception 'locked capture-mismatch error left lease stranded';end if;

